CREATE TABLE public.agri_imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,source_name text NOT NULL,source_url text NOT NULL,filename text NOT NULL,raw_text text NOT NULL,accepted integer NOT NULL DEFAULT 0,rejected integer NOT NULL DEFAULT 0,duplicates integer NOT NULL DEFAULT 0,errors jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,DELETE ON public.agri_imports TO authenticated; GRANT ALL ON public.agri_imports TO service_role; ALTER TABLE public.agri_imports ENABLE ROW LEVEL SECURITY; CREATE POLICY own_import_read ON public.agri_imports FOR SELECT TO authenticated USING(owner_id=auth.uid()); CREATE POLICY own_import_insert ON public.agri_imports FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid()); CREATE POLICY own_import_delete ON public.agri_imports FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE TABLE public.agri_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),import_id uuid REFERENCES public.agri_imports(id) ON DELETE CASCADE,owner_id uuid,official boolean NOT NULL DEFAULT false,state text NOT NULL,district text NOT NULL,market text NOT NULL,commodity text NOT NULL,variety text NOT NULL,date date NOT NULL,min_price numeric,max_price numeric,modal_price numeric NOT NULL CHECK(modal_price>0 AND modal_price<1000000000),price_unit text NOT NULL DEFAULT 'INR/quintal' CHECK(price_unit='INR/quintal'),arrivals numeric,arrival_unit text,source_name text NOT NULL,source_url text NOT NULL,retrieved_at timestamptz NOT NULL DEFAULT now(),suspicious boolean NOT NULL DEFAULT false,CHECK(min_price IS NULL OR min_price<=modal_price),CHECK(max_price IS NULL OR max_price>=modal_price)); GRANT SELECT ON public.agri_reports TO anon; GRANT SELECT,INSERT,DELETE ON public.agri_reports TO authenticated; GRANT ALL ON public.agri_reports TO service_role; ALTER TABLE public.agri_reports ENABLE ROW LEVEL SECURITY; CREATE POLICY public_or_own_reports ON public.agri_reports FOR SELECT TO anon,authenticated USING(official OR owner_id=auth.uid()); CREATE POLICY private_insert ON public.agri_reports FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND official=false AND EXISTS(SELECT 1 FROM public.agri_imports i WHERE i.id=import_id AND i.owner_id=auth.uid())); CREATE POLICY own_delete ON public.agri_reports FOR DELETE TO authenticated USING(owner_id=auth.uid() AND NOT official); CREATE UNIQUE INDEX agri_report_unique ON public.agri_reports(import_id,state,district,market,commodity,variety,date); CREATE INDEX agri_report_filter ON public.agri_reports(state,district,commodity,variety,date DESC);
CREATE TABLE public.agri_source_checks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source text NOT NULL,status text NOT NULL,message text NOT NULL,checked_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.agri_source_checks TO anon,authenticated; GRANT ALL ON public.agri_source_checks TO service_role; ALTER TABLE public.agri_source_checks ENABLE ROW LEVEL SECURITY; CREATE POLICY source_read ON public.agri_source_checks FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.agri_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,kind text NOT NULL,status text NOT NULL,parameters jsonb NOT NULL DEFAULT '{}',result jsonb,message text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.agri_jobs TO authenticated; GRANT ALL ON public.agri_jobs TO service_role; ALTER TABLE public.agri_jobs ENABLE ROW LEVEL SECURITY; CREATE POLICY job_read ON public.agri_jobs FOR SELECT TO authenticated USING(owner_id=auth.uid()); CREATE POLICY job_insert ON public.agri_jobs FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid()); CREATE POLICY job_update ON public.agri_jobs FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE FUNCTION public.agri_catalog(f jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('states',COALESCE(jsonb_agg(DISTINCT state),'[]'),'districts',COALESCE(jsonb_agg(DISTINCT district),'[]'),'markets',COALESCE(jsonb_agg(DISTINCT market),'[]'),'commodities',COALESCE(jsonb_agg(DISTINCT commodity),'[]'),'varieties',COALESCE(jsonb_agg(DISTINCT variety),'[]'),'sources',COALESCE(jsonb_agg(DISTINCT source_name),'[]')) FROM public.agri_reports WHERE (COALESCE(f->>'state','')='' OR state=f->>'state') AND (COALESCE(f->>'district','')='' OR district=f->>'district') AND (COALESCE(f->>'market','')='' OR market=f->>'market') AND (COALESCE(f->>'commodity','')='' OR commodity=f->>'commodity') AND (COALESCE(f->>'variety','')='' OR variety=f->>'variety') AND (COALESCE(f->>'source','')='' OR source_name=f->>'source'); $$; GRANT EXECUTE ON FUNCTION public.agri_catalog(jsonb) TO anon,authenticated,service_role;
CREATE FUNCTION public.agri_coverage(f jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH r AS (SELECT * FROM public.agri_reports WHERE (COALESCE(f->>'state','')='' OR state=f->>'state') AND (COALESCE(f->>'district','')='' OR district=f->>'district') AND (COALESCE(f->>'commodity','')='' OR commodity=f->>'commodity') AND (COALESCE(f->>'variety','')='' OR variety=f->>'variety')) SELECT jsonb_build_object('records',count(*),'states',count(DISTINCT state),'districts',count(DISTINCT (state,district)),'markets',count(DISTINCT (state,district,market)),'commodities',count(DISTINCT commodity),'varieties',count(DISTINCT variety),'earliest',min(date),'latest',max(date),'last_update',max(retrieved_at),'missing_prices',count(*) FILTER(WHERE min_price IS NULL OR max_price IS NULL),'missing_arrivals',count(*) FILTER(WHERE arrivals IS NULL),'outliers',count(*) FILTER(WHERE suspicious),'state_coverage',(SELECT COALESCE(jsonb_agg(s),'[]') FROM (SELECT state,count(*) records FROM r GROUP BY state ORDER BY state)s)) FROM r; $$; GRANT EXECUTE ON FUNCTION public.agri_coverage(jsonb) TO anon,authenticated,service_role;